import {MazeGame,DIRECTIONS} from './maze-engine.js';
import {loadWords} from './word-store.js';
import {readWords} from './vocab.js';
import {bindGameLifecycle} from './game-lifecycle.js';
const $=id=>document.getElementById(id);let game=null,paused=false,last=0,held=null,pointerId=null,finished=false,messageUntil=0;
for(let i=0;i<81;i++){const c=document.createElement('div');c.className='cell';$('maze').append(c);}
function clear(){held=null;pointerId=null;}
function note(t){$('status').textContent=t;messageUntil=performance.now()+1700;}
function start(){const p=readWords(loadWords());try{if(p.errors.length)throw Error(p.errors[0]);game=new MazeGame(p.entries);}catch(e){$('error').textContent=e.message;return;}clear();paused=false;finished=false;for(const id of['intro','result','quizScreen','pauseScreen'])$(id).classList.add('hidden');note('爆弾を置いたら、曲がり角へ逃げよう！');render();}
function render(){if(!game)return;const g=game;[...$('maze').children].forEach((c,i)=>{const x=i%9,y=Math.floor(i/9),tile=g.grid[y][x],bomb=g.bombs.find(b=>b.x===x&&b.y===y),fire=g.flames.some(f=>f.x===x&&f.y===y),enemy=g.enemies.some(e=>e.x===x&&e.y===y),player=g.player.x===x&&g.player.y===y,exit=x===7&&y===7;c.className='cell'+(tile===1?' hard':tile===2?' crate':'')+(exit?' exit':'')+(exit&&!g.enemies.length?' unlocked':'')+(fire?' fire':'')+(player&&g.invincible>0?' invincible':'');c.textContent=player?'🐥':fire?'✹':bomb?'💣':enemy?'👾':exit?(g.enemies.length?'🔒':'🚪'):tile===2?'╳':'';if(bomb){const small=document.createElement('small');small.textContent=Math.ceil(bomb.life);c.append(small);}});$('health').textContent='♥'.repeat(g.hp)+'♡'.repeat(3-g.hp);$('time').textContent=Math.ceil(g.time)+'秒';$('ammo').textContent='爆弾 '+g.ammo;$('place').disabled=paused||!!g.quiz||g.mode!=='play'||!g.ammo||g.bombs.length>=2;$('refill').disabled=paused||!!g.quiz||g.mode!=='play'||g.ammo>=4;if(performance.now()>messageUntil)$('status').textContent=g.enemies.length?'敵あと'+g.enemies.length+'体 · 木箱破壊 '+g.destroyed:'出口が開いた！ 右下のドアへ';if(g.mode!=='play'&&!finished){finished=true;clear();$('resultTitle').textContent=g.mode==='won'?'迷路から脱出！':'もう一度チャレンジ！';$('resultScore').textContent='敵 '+g.kills+' / 3体';$('resultStats').textContent=`木箱${g.destroyed}個破壊 · 単語${g.correct}/${g.answered}問正解`;$('review').replaceChildren();for(const p of g.review.values()){const r=document.createElement('p');r.textContent=p.word+' ＝ '+p.meaning;$('review').append(r);}$('result').classList.remove('hidden');}}
function pause(v){if(!game||game.mode!=='play')return;paused=v;clear();$('pauseScreen').classList.toggle('hidden',!v);render();}
for(const b of document.querySelectorAll('[data-dir]')){b.addEventListener('pointerdown',e=>{if(!game||paused||game.quiz||game.mode!=='play'||pointerId!==null)return;e.preventDefault();pointerId=e.pointerId;held=Number(b.dataset.dir);try{b.setPointerCapture(e.pointerId);}catch{}game.move(...DIRECTIONS[held]);render();});for(const event of['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,e=>{if(e.pointerId===pointerId)clear();});b.addEventListener('contextmenu',e=>e.preventDefault());}
function refill(){if(!game||paused||!game.openQuiz())return;clear();$('quizTitle').textContent=game.quiz.target.meaning;$('quizFeedback').textContent='正解で爆弾を2個補充！';$('closeQuiz').textContent='補充せずに戻る';$('choices').replaceChildren();game.quiz.choices.forEach((p,i)=>{const b=document.createElement('button');b.className='secondary';b.textContent=p.word;b.onclick=()=>{if(paused)return;const ok=game.answerQuiz(i);if(ok===null)return;for(const n of $('choices').children)n.disabled=true;$('quizFeedback').textContent=ok?'正解！ 爆弾 ＋2':`正解は ${game.quiz.target.word} ＝ ${game.quiz.target.meaning}`;$('closeQuiz').textContent='迷路に戻る';render();};$('choices').append(b);});$('quizScreen').classList.remove('hidden');render();}
$('start').onclick=start;$('again').onclick=start;$('place').onclick=()=>{if(!paused){if(game?.place())note('置いた！ 爆風から逃げよう！');else note('爆弾を補充するか、置いた爆弾の爆発を待とう');render();}};$('refill').onclick=refill;$('closeQuiz').onclick=()=>{game?.closeQuiz();clear();$('quizScreen').classList.add('hidden');render();};$('pause').onclick=()=>pause(true);$('resume').onclick=()=>pause(false);bindGameLifecycle(window,document,{clearInput:reason=>{if(reason!=='blur'||pointerId===null)clear();},pause});
const keyDirs={ArrowUp:0,w:0,ArrowRight:1,d:1,ArrowDown:2,s:2,ArrowLeft:3,a:3};window.addEventListener('keydown',e=>{if(e.key==='Escape'){pause(!paused);return;}if(!game||paused||game.quiz||game.mode!=='play')return;const d=keyDirs[e.key];if(d!==undefined){e.preventDefault();held=d;}if(e.code==='Space'){e.preventDefault();if(!e.repeat)$('place').click();}if(e.key==='q'&&!e.repeat)refill();});window.addEventListener('keyup',e=>{if(keyDirs[e.key]!==undefined)clear();});function frame(t){const dt=last?Math.min(.1,(t-last)/1000):0;last=t;if(game&&!paused&&!document.hidden&&game.mode==='play'){game.tick(dt);if(held!==null)game.move(...DIRECTIONS[held]);render();}requestAnimationFrame(frame);}requestAnimationFrame(frame);
